// 作用：标准化表单上传文件，只做内存字段整理。
// 不使用 fs、不读写任何本地目录。
const item = $input.first();
const binary = item.binary || {};
const firstBinaryKey = Object.keys(binary)[0];

if (!firstBinaryKey) {
  throw new Error('没有收到 CSV 文件。请在表单的 health_topics_csv 字段上传 .csv 文件。');
}

const limitFromForm = Number(item.json.today_limit || 5);
const safeLimit = Number.isFinite(limitFromForm) && limitFromForm > 0 ? Math.floor(limitFromForm) : 5;

return [{
  json: {
    today_limit: safeLimit,
    today_focus: item.json.today_focus || ''
  },
  binary: {
    data: binary[firstBinaryKey]
  }
}];

// Agent 1 Memory MVP v2：只要求 title 必填，其他字段全部可选。
// 只做数据处理，不操作文件系统，不使用 fs / require。
function toScore(value, fallback) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(1, Math.min(5, Math.round(number)));
}

function escapeRegex(word) {
  return word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function containsWord(text, word) {
  return new RegExp('(^|[^a-zA-Z])' + escapeRegex(word) + '($|[^a-zA-Z])', 'i').test(text);
}

function normalizeText(value) {
  return String(value || '').trim();
}

function getField(row, names) {
  for (const name of names) {
    if (row[name] !== undefined && normalizeText(row[name]) !== '') return row[name];
  }
  return '';
}

function getFirstNonEmptyValue(row) {
  for (const value of Object.values(row)) {
    const text = normalizeText(value);
    if (text) return text;
  }
  return '';
}

function inferIngredient(title) {
  const lower = title.toLowerCase();
  if (lower.includes('rooibos')) return 'Rooibos';
  if (lower.includes('ginger')) return 'Ginger';
  if (lower.includes('goji')) return 'Goji berry';
  if (lower.includes('turmeric')) return 'Turmeric';
  if (lower.includes('tea')) return 'Tea / botanical';
  if (lower.includes('herb')) return 'General herb';
  return 'General wellness';
}

function inferAngle(title) {
  const lower = title.toLowerCase();
  if (lower.includes('caffeine') || lower.includes('evening') || lower.includes('night')) return 'daily routine / caffeine-free habit';
  if (lower.includes('screen') || lower.includes('eye') || lower.includes('fatigue')) return 'screen fatigue / daily comfort';
  if (lower.includes('after meal') || lower.includes('digestion') || lower.includes('dinner')) return 'after-meal wellness ritual';
  if (lower.includes('south africa') || lower.includes('african')) return 'botanical story / origin education';
  return 'general wellness curiosity';
}

function inferTargetAudience(title) {
  const lower = title.toLowerCase();
  if (lower.includes('coffee') || lower.includes('caffeine')) return 'US adults who drink coffee or tea';
  if (lower.includes('screen') || lower.includes('office')) return 'US office workers and screen users';
  if (lower.includes('beginner')) return 'US wellness beginners';
  return 'US wellness audience';
}

function inferCuriosity(title) {
  const lower = title.toLowerCase();
  if (lower.includes('why') || lower.includes('?') || lower.includes('secret') || lower.includes('hidden')) return 5;
  if (lower.includes('what') || lower.includes('how') || lower.includes('vs')) return 4;
  return 3;
}

function inferPain(title) {
  const lower = title.toLowerCase();
  if (lower.includes('fatigue') || lower.includes('pain') || lower.includes('sleep') || lower.includes('heavy') || lower.includes('stress')) return 4;
  if (lower.includes('caffeine') || lower.includes('coffee') || lower.includes('screen') || lower.includes('after meal')) return 3;
  return 2;
}

function inferProductFit(title, ingredient) {
  const lower = title.toLowerCase();
  if (ingredient !== 'General wellness' && ingredient !== 'General herb') return 4;
  if (lower.includes('tea') || lower.includes('herb') || lower.includes('botanical')) return 4;
  return 3;
}

function inferVisualPotential(title) {
  const lower = title.toLowerCase();
  if (lower.includes('tea') || lower.includes('routine') || lower.includes('meal') || lower.includes('screen')) return 4;
  return 3;
}

function inferRepeatability(title) {
  const lower = title.toLowerCase();
  if (lower.includes('routine') || lower.includes('beginner') || lower.includes('vs') || lower.includes('why')) return 4;
  return 3;
}

function riskInfo(topic) {
  const combined = [topic.title, topic.ingredient, topic.angle, topic.target_audience, topic.suggested_hook].join(' ');
  const highRiskWords = ['cure', 'cures', 'treat', 'treats', 'treatment', 'prevent', 'prevents', 'reverse', 'reverses', 'diabetes', 'cancer', 'hypertension'];
  const mediumRiskWords = ['pain', 'inflammation', 'blood sugar', 'detox', 'cleanse'];
  const lowRiskWords = ['tea', 'caffeine', 'routine', 'evening routine', 'screen fatigue'];

  const highHits = highRiskWords.filter((word) => containsWord(combined, word));
  const mediumHits = mediumRiskWords.filter((word) => combined.toLowerCase().includes(word.toLowerCase()));
  const lowHits = lowRiskWords.filter((word) => combined.toLowerCase().includes(word.toLowerCase()));

  if (highHits.length > 0) {
    return {
      risk_score: 5,
      risk_level: 'High',
      risk_alert: '包含高风险健康词：' + highHits.join(', ') + '。不要直接制作，必须先改写。'
    };
  }
  if (mediumHits.length > 0) {
    return {
      risk_score: 3,
      risk_level: 'Medium',
      risk_alert: '包含中等风险健康表达：' + mediumHits.join(', ') + '。建议弱化为日常健康习惯表达。'
    };
  }
  if (lowHits.length > 0) {
    return {
      risk_score: 1,
      risk_level: 'Low',
      risk_alert: '偏日常健康习惯，命中低风险方向：' + lowHits.join(', ') + '。'
    };
  }
  return {
    risk_score: 1,
    risk_level: 'Low',
    risk_alert: '未发现明显高风险词，但仍需人工确认。'
  };
}

function focusBonus(topic, todayFocus) {
  const focus = normalizeText(todayFocus).toLowerCase();
  if (!focus) return 0;

  const combined = [topic.title, topic.ingredient, topic.angle, topic.target_audience, topic.suggested_hook].join(' ').toLowerCase();
  const tokens = focus.split(/[^a-zA-Z0-9]+/).filter((token) => token.length >= 3);
  if (tokens.length === 0) return 0;

  const matched = tokens.filter((token) => combined.includes(token));
  if (matched.length === 0) return 0;
  return Math.min(5, matched.length * 2);
}

function recommendationFor(score, riskLevel) {
  if (riskLevel === 'High') return 'No';
  if (score >= 18) return 'Yes';
  return 'No';
}

const setup = $items('2. 标准化上传文件')[0].json;
const limit = Number(setup.today_limit || 5);
const todayFocus = setup.today_focus || '';
const rows = $input.all().map((item) => item.json);

if (rows.length === 0) {
  throw new Error('CSV 转换后没有任何数据行，请检查上传的 CSV。');
}

const scored = rows.map((row, index) => {
  const title = normalizeText(getField(row, ['title', 'topic', 'Title', 'Topic']) || getFirstNonEmptyValue(row));
  if (!title) {
    throw new Error('第 ' + (index + 2) + ' 行缺少 title。最简 CSV 也必须至少有 title。');
  }

  const ingredient = normalizeText(getField(row, ['ingredient', 'herb', 'Ingredient', 'Herb']) || inferIngredient(title));
  const angle = normalizeText(getField(row, ['angle', 'Angle']) || inferAngle(title));
  const targetAudience = normalizeText(getField(row, ['target_audience', 'audience', 'Target Audience']) || inferTargetAudience(title));
  const suggestedHook = normalizeText(getField(row, ['suggested_hook', 'hook', 'Hook']) || title);

  const curiosity = toScore(row.curiosity, inferCuriosity(title));
  const pain = toScore(row.pain, inferPain(title));
  const productFit = toScore(row.product_fit, inferProductFit(title, ingredient));
  const visualPotential = toScore(row.visual_potential, inferVisualPotential(title));
  const repeatability = toScore(row.repeatability, inferRepeatability(title));

  const topic = {
    title,
    ingredient,
    angle,
    target_audience: targetAudience,
    suggested_hook: suggestedHook
  };

  const risk = riskInfo(topic);
  const bonus = focusBonus(topic, todayFocus);
  const score = curiosity * 2 + pain * 2 + productFit + visualPotential + repeatability + bonus - risk.risk_score * 2;
  const recommendation = recommendationFor(score, risk.risk_level);
  const reason = recommendation === 'Yes'
    ? '推荐制作：即使 CSV 只提供标题，系统也根据标题补全了角度、人群和基础评分，当前分数与风险可控。'
    : risk.risk_level === 'High'
      ? '暂缓制作：标题中存在高风险健康表达，需要先改写。'
      : '暂缓制作：根据标题推断的综合分数偏低，建议优化标题、痛点或画面表达。';

  return {
    ranking: 0,
    row_number: index + 2,
    topic: title,
    title,
    ingredient,
    angle,
    target_audience: targetAudience,
    score,
    recommendation,
    reason,
    risk_level: risk.risk_level,
    risk_alert: risk.risk_alert,
    focus_bonus: bonus,
    suggested_hook: suggestedHook,
    inferred_defaults_used: {
      ingredient: getField(row, ['ingredient', 'herb', 'Ingredient', 'Herb']) ? 'No' : 'Yes',
      angle: getField(row, ['angle', 'Angle']) ? 'No' : 'Yes',
      target_audience: getField(row, ['target_audience', 'audience', 'Target Audience']) ? 'No' : 'Yes',
      suggested_hook: getField(row, ['suggested_hook', 'hook', 'Hook']) ? 'No' : 'Yes'
    }
  };
});

const ranked = scored
  .sort((a, b) => b.score - a.score)
  .slice(0, limit)
  .map((item, index) => ({ ...item, ranking: index + 1 }));

const markdownLines = [];
markdownLines.push('# AI Health OS - Agent 1 Memory MVP v2 决策报告');
markdownLines.push('');
markdownLines.push('## 今日推荐 Top ' + ranked.length + ' 选题');
markdownLines.push('');
if (todayFocus) {
  markdownLines.push('- 今日重点方向：' + todayFocus);
  markdownLines.push('');
}
markdownLines.push('| 排名 | 选题 | 分数 | 推荐 | 风险等级 |');
markdownLines.push('| --- | --- | ---: | --- | --- |');
ranked.forEach((item) => {
  markdownLines.push('| ' + item.ranking + ' | ' + item.title + ' | ' + item.score + ' | ' + item.recommendation + ' | ' + item.risk_level + ' |');
});
markdownLines.push('');
markdownLines.push('## 详细说明');
ranked.forEach((item) => {
  markdownLines.push('');
  markdownLines.push('### ' + item.ranking + '. ' + item.title);
  markdownLines.push('- 分数：' + item.score);
  markdownLines.push('- 推荐：' + item.recommendation);
  markdownLines.push('- 推荐原因：' + item.reason);
  markdownLines.push('- 风险等级：' + item.risk_level);
  markdownLines.push('- 风险提醒：' + item.risk_alert);
  markdownLines.push('- 自动补全 ingredient：' + item.ingredient);
  markdownLines.push('- 自动补全 angle：' + item.angle);
  markdownLines.push('- 自动补全 target_audience：' + item.target_audience);
  markdownLines.push('- 今日重点加分：' + item.focus_bonus);
  markdownLines.push('- 开头钩子：' + item.suggested_hook);
});
markdownLines.push('');
markdownLines.push('## 下一步');
markdownLines.push('请先人工确认这份报告。确认前不要开发 Agent 2。');

return [{
  json: {
    workflow_name: 'AI Health OS - Agent 1 Memory MVP v2',
    today_limit: limit,
    today_focus: todayFocus,
    ranked_topics: ranked,
    markdown_report: markdownLines.join('\n')
  }
}];

// JSON 最终输出分支：只输出排名结果，方便复制或给后续 Agent 使用。
const analysis = $input.first().json;
return [{
  json: {
    output_type: 'json_ranking_result',
    workflow_name: analysis.workflow_name,
    today_limit: analysis.today_limit,
    today_focus: analysis.today_focus,
    ranked_topics: analysis.ranked_topics
  }
}];

// Markdown 最终输出分支：输出给产品经理阅读的决策报告。
const analysis = $input.first().json;
return [{
  json: {
    output_type: 'markdown_decision_report',
    workflow_name: analysis.workflow_name,
    markdown_report: analysis.markdown_report,
    ranked_topics: analysis.ranked_topics
  }
}];
